ALTER TABLE "dmps" ADD CONSTRAINT "dmps_draft_object_keys" CHECK ("dmps"."draft" = '{}'::jsonb or (jsonb_typeof("dmps"."draft") = 'object' and not exists (select 1 from jsonb_object_keys("dmps"."draft") k where k not in ('dmp_id', 'project_id', 'title', 'description', 'language', 'alternate_identifier', 'begin_date', 'end_date', 'ethical_issues_exist', 'ethical_issues_description', 'ethical_issues_report', 'indigenous_considerations', 'contributor', 'cost', 'dataset', 'schema_version'))));